 if(typeof loadClaimmdProviderDefaults==='function')await loadClaimmdProviderDefaults();if(!claimContextCurrent(context))return;
 const [c,r,p,s,claimmd]=await Promise.all([api(`${claimsBase}${afterClaim?'?after='+afterClaim:''}`),api(`${eraBase}${afterEra?'?after='+afterEra:''}`),api('/api/v1/billing/payers'),billingWrite()?api('/api/v1/billing/remittance-sources'):{items:[]},loadClaimMdConnection()]);
 if(!claimContextCurrent(context))return;
 claimRows=c.items;eraRows=r.items;billingPayers=p.items;claimNext=c.next_cursor;eraNext=r.next_cursor;showTool('Claims & remittances');
 $('tools').innerHTML=`<section id="claims-tool"><div class="section-head"><div><h2>Claims and insurance payments</h2><p class="muted">Review claims, payer responses, and payments that need staff action.</p></div><button type="button" data-claims-refresh>Refresh</button></div><div class="billing-totals"><span>Claims <b>${c.items.length}</b></span><span>Payments to review <b>${r.items.filter(x=>['staged','reconciled'].includes(x.status)).length}</b></span><span>Payments posted <b>${r.items.filter(x=>x.status==='posted').length}</b></span></div>
 <section class="billing-section"><div class="section-head"><div><h3>Claims needing action</h3><p class="muted">Open a claim to review it, send it through Claim.MD, or record a payer response.</p></div></div><div class="billing-table-wrap"><table class="billing-table"><thead><tr><th>Patient</th><th>Payer</th><th>Status</th><th class="money-cell">Billed</th><th></th></tr></thead><tbody>${c.items.map(v=>`<tr><td><b>${esc(v.patient_name)}</b><small class="claim-control">Claim ${esc(v.control_number)}</small></td><td>${esc(v.payer_name)}<small>${esc(human(v.frequency))}</small></td><td><span class="pill">${esc(human(v.status))}</span></td><td class="money-cell">${money(v.total_cents)}</td><td><button type="button" data-claim-open="${v.id}">Open claim</button></td></tr>`).join('')||'<tr><td colspan="5" class="table-empty">No claims need attention.</td></tr>'}</tbody></table></div>${claimNext?'<button type="button" data-claims-next>Show more claims</button>':''}</section>
 <section class="billing-section"><div class="section-head"><div><h3>Insurance payments</h3><p class="muted">Claim.MD payments appear automatically for review before posting to patient accounts.</p></div></div><div class="billing-table-wrap"><table class="billing-table"><thead><tr><th>Payer / trace</th><th>Payment date</th><th>Claims</th><th>Status</th><th class="money-cell">Payment</th><th></th></tr></thead><tbody>${r.items.map(v=>`<tr><td><b>${esc(v.payer_name)}</b><small>${esc(v.trace)}</small></td><td>${esc(v.payment_date)}</td><td>${v.claim_count}</td><td><span class="pill">${esc(human(v.status))}</span></td><td class="money-cell">${money(v.total_paid_cents)}</td><td><button type="button" data-era-open="${v.id}">Review payment</button></td></tr>`).join('')||'<tr><td colspan="6" class="table-empty">No insurance payments need review.</td></tr>'}</tbody></table></div>${eraNext?'<button type="button" data-era-next>Show more payments</button>':''}</section>
 ${s.items.length?`<details class="amendment"><summary>Imported remittance sources (${s.items.length})</summary>${s.items.map(v=>`<div class="timeline-row"><div><b>${esc(v.source_id)}</b><small>${esc(v.source_instance)}</small></div><button type="button" data-era-source="${v.source_history_id}">${v.native_id?'View reconciled ERA':'Review source mapping'}</button></div>`).join('')}</details>`:''}<div id="claims-detail"></div></section>`;
 context.host=$('claims-detail');
 await showEraAutomation('claims-detail','beforebegin');
 if(!claimContextCurrent(context))return;await showRecoupments();
