async function showClaim(id){
 const context=claimContextSnapshot(),identity=typeof me==='undefined'?undefined:me;
 const [d,h]=await Promise.all([api(`${claimsBase}/${id}`),api(`${claimsBase}/${id}/history`)]);if(!claimContextCurrent(context)||identity!==(typeof me==='undefined'?undefined:me))return;requireClaimContext(context,d.claim);claimCurrent=d.claim;context.claim=d.claim.id;const c=d.claim,b=c.snapshot.account,p=c.snapshot.patient;
 const fs=c.snapshot.financial_summary||{patient_payments_cents:0,open_balance_cents:b.total_cents};
 claimPane(`<section class="billing-account-detail"><div class="section-head"><div><h2>Claim review</h2><p>${esc(p.given_name)} ${esc(p.family_name)} · Service ${esc(b.content.service_date)}</p><small class="claim-control" data-claim-current-version>${esc(c.control_number)} · v${c.version}</small></div><span class="status-badge" data-claim-current-status>${esc(c.status)}</span></div>${claimPrimaryActions(c,d)}${secondaryEvidenceMarkup(c)}<div class="billing-totals"><span>Gross professional charge <b>${money(b.total_cents)}</b></span><span>Copay / patient payment recorded <b>${money(fs.patient_payments_cents||0)}</b></span><span>Expected insurer balance <b>${money(fs.open_balance_cents??b.total_cents)}</b></span><span>Frequency <b>${esc(human(c.frequency))}</b></span><span>Payer <b>${esc(b.coverage_snapshot.payer.content.name)}</b></span></div><p class="muted">The 837P and CMS-1500 carry the gross charge. The copay remains linked to the patient ledger, and the remaining expected insurer balance is frozen here for reconciliation.</p>${c.parent_id?`<button type="button" data-claim-open="${c.parent_id}">Review original claim</button>`:''}${claimIssues(d.preflight_issues)}${chargeTable(b.content.lines.map((line,i)=>({...line,diagnosis_codes:(c.content.line_diagnosis_pointers[i]||[]).map(n=>c.content.diagnosis_codes[n-1]).filter(Boolean)})))}<details class="amendment"><summary>Provider, insurance and diagnosis details</summary><dl class="billing-dl">${Object.entries(c.content).map(([k,v])=>`<dt>${esc(human(k))}</dt><dd>${esc(Array.isArray(v)?JSON.stringify(v):v??'Not recorded')}</dd>`).join('')}</dl><pre class="billing-source">${esc(JSON.stringify(b.coverage_snapshot,null,2))}</pre></details><div class="actions"><button type="button" data-claim-account="${c.account_id}" data-patient="${c.patient_id}">Encounter charges & payments</button>${c.status!=='draft'&&c.status!=='void'?`<a class="button" href="${claimsBase}/${c.id}/packet" download>Export claim packet (JSON)</a>`:''}${billingWrite()&&c.status==='draft'?'<button type="button" data-edit-claim>Edit claim details</button>':''}${billingWrite()&&c.status==='adjudicated'&&b.coverage_snapshot?.coverage?.content?.priority==='primary'?'<button type="button" data-secondary-claim>Review secondary billing</button>':''}${billingWrite()&&(c.status==='rejected'||c.status==='adjudicated'&&c.payer_control_number)?'<button type="button" data-replacement-claim>Prepare corrected / linked claim</button>':''}</div><p class="muted">${claimTransport(d.transport)}</p>
 ${billingWrite()&&['draft','ready','submitted','accepted'].includes(c.status)?`${c.status!=='draft'?'<details class="amendment"><summary>Record activity completed outside SunCharts</summary>':''}<form id="claim-action"><h3>${c.status==='draft'?'Review claim readiness':'Record external claim activity'}</h3><div class="form-grid"><label>Action<select name="action">${(c.status==='draft'?['ready','void_draft']:c.status==='ready'?['record_submission','void_draft']:c.status==='submitted'?['record_acceptance','record_rejection']:['record_rejection']).map(v=>`<option value="${v}">${esc(human(v))}</option>`).join('')}</select></label>${c.status==='draft'?'':`${billingField('reference','External submission / response reference','','text',200)}${billingField('event_date','External event date','','date')}${billingField('payer_control_number','Payer claim control number',c.payer_control_number,'text',100)}`}${billingField('reason','Review / evidence reason','','text',1000,true)}</div><p class="muted">${c.status==='draft'?'Marking ready saves the reviewed claim for a separate submission step. It does not send it to insurance.':c.status==='ready'?'Use this form only to record a submission already made outside this EHR, or to void the ready claim. To send through Claim.MD from here, use Review & submit to Claim.MD above.':'Record evidence of an acceptance or rejection received outside this workflow. This does not send a claim or record an insurance payment.'}</p><button class="primary" type="submit">${c.status==='draft'?'Save review decision':'Record external activity'}</button></form>${c.status!=='draft'?'</details>':''}`:''}<h3>Claim history</h3>${claimHistory(h)}<div id="claim-editor"></div></section>`);

 const lifecycle=typeof claimMdClaimLifecycle==='function'?claimMdClaimLifecycle(c,d,h):'';
 if(lifecycle)claimWorkspaceHost(context).querySelector('.billing-account-detail').insertAdjacentHTML('afterbegin',lifecycle);
 const action=$('claim-action');if(action){action.claimViewContext=context;action.claimRecord=c;}
 if(typeof startClaimMdTracking==='function')startClaimMdTracking(c.id);
 if(typeof showClaimMdClaimActivity==='function')await showClaimMdClaimActivity(c);
}
function claimChargeDiagnosisDefaults(account){
 const diagnosisCodes=[],pointers=(account.content.lines||[]).map(line=>{
  const codes=[...new Set((Array.isArray(line.diagnosis_codes)?line.diagnosis_codes:[]).filter(code=>typeof code==='string'&&code.trim()).map(code=>code.trim()))];
  return codes.map(code=>{let index=diagnosisCodes.indexOf(code);if(index<0){index=diagnosisCodes.length;diagnosisCodes.push(code);}return index+1;});
 });
 return {diagnosis_codes:diagnosisCodes,line_diagnosis_pointers:pointers};
}
function secondaryEvidenceMarkup(claim){
 const e=claim.snapshot?.coordination_of_benefits;if(!e)return '';
 return `<section class="mapping-notice"><h3>Secondary claim · same encounter charges</h3><p>Primary: ${esc(e.primary_coverage?.payer?.content?.name||'Recorded primary payer')} · Paid ${money(e.adjudication.paid_cents)} · Patient responsibility reported ${money(e.adjudication.patient_responsibility_cents)} · Remit ${esc(e.payment_date)}</p><p>Primary claim ${esc(e.adjudication.payer_control_number)} · Trace ${esc(e.trace)}</p><p>Crossover and submission timing reviewed: ${esc(e.crossover_reference)}</p><details><summary>Frozen primary payment & adjustment evidence</summary><pre class="billing-source">${esc(JSON.stringify(e.adjudication,null,2))}</pre></details><p class="muted">No second charge account or service was created. The primary payment remains on the same ledger. The secondary payer receives the original charges and the primary adjudication evidence.</p></section>`;
}
